import itertools

def count_good_paths(board):
    rows = len(board)
    cols = len(board[0])

    # W(x) = 1 + sum(W(y) for y in N(x) if v(y) > v(x))
    # We can compute W(x) in decreasing order of v(x)
    cells = []
    for r in range(rows):
        for c in range(cols):
            cells.append((board[r][c], r, c))
    cells.sort(key=lambda x: x[0], reverse=True)

    W = {}
    for val, r, c in cells:
        neighbors = []
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                neighbors.append((nr, nc))

        sum_W = 0
        for nr, nc in neighbors:
            if board[nr][nc] > val:
                sum_W += W[(board[nr][nc], nr, nc)]
        W[(val, r, c)] = 1 + sum_W

    total_good_paths = 0
    for r in range(rows):
        for c in range(cols):
            val = board[r][c]
            is_start = True
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if board[nr][nc] < val:
                        is_start = False
                        break
            if is_start:
                total_good_paths += W[(val, r, c)]

    return total_good_paths

